const nm = k => typeof k.key_name === 'object' ? (k.key_name.web || k.key_name.other) : k.key_name;
const RE = /^components::members::profile::(?:introduction::)?(et|anxiety|bt|occ|ps|so|ocd|ndt|nd|maiden|lover|nurturer|queen|warrior|sage|mystic|rebel|ma_[a-z]+)::(.+)::content::(start|end|list::\d+)$/;
const groups = {};
for (const it of $input.all()) { if (!Array.isArray(it.json.keys)) throw new Error('no keys'); for (const k of it.json.keys) { const n = nm(k) || ''; const m = n.match(RE); if (!m) continue; const g = n.replace(/::content::(start|end|list::\d+)$/, ''); (groups[g] = groups[g] || []).push([k.key_id, m[3], m[1]]); } }
const keep = Object.entries(groups).filter(([g, a]) => a.some(x => x[1] === 'start') && a.filter(x => x[1].startsWith('list')).length >= 2);
const FA = ['maiden','lover','nurturer','queen','warrior','sage','mystic','rebel'];
const gmap = {}; const ids = []; for (const [g, a] of keep) for (const [id, part, t] of a) { ids.push(id); gmap[id] = [g, part, FA.includes(t) ? 'fa' : (t.startsWith('ma_') ? 'ma' : t)]; }
const out = []; for (let i = 0; i < ids.length; i += 100) out.push({ json: { ng: keep.length, n: ids.length, url: 'https://api.lokalise.com/api2/projects/31393214664f295f94dd86.76792605/keys?limit=100&include_translations=1&disable_references=1&filter_translation_lang_ids=640,767,666,1056,10154,673,757,734,733,10152,10153,749,737,760,748,708,770,754,753&filter_key_ids=' + ids.slice(i, i+100).join(',') } });
out[0].json.gmap = gmap; return out;

const LING = ["47natcha@gmail.com", "arandatrad@gmail.com", "austra.muizniece@gmail.com", "boh.vozniuk@gmail.com", "bruno@bsttranslations.com", "daniel@dgmultilingualservices.com", "dmluciahorea@gmail.com", "ellen.de.venter@outlook.com", "farahputri@gmail.com", "harald.roald@gmail.com", "ilaria.roncaglia@gmail.com", "ivanaturcin@ymail.com", "jaromirvicari@me.com", "julius.valkiunas@gmail.com", "karahansisman@gmail.com", "katri.varvikko@gmail.com", "kenneth@phraseit.dk", "marit.teichmann@gmail.com", "michal.tosza@translators.org.pl", "mjlocalize@gmail.com", "mteixeira@sacradomus.com", "mteres@terestraducciones.com", "nerissaneptuno@gmail.com", "qrcodelocalization@gmail.com", "quentinnguyen.localize@gmail.com", "root-translations@outlook.com", "roxanamoldovan25@gmail.com", "ruckova.lucia@gmail.com", "sabrathan@gmail.com", "sara.guinot.trad@gmail.com", "silis.martins@gmail.com", "silke.luehrmann@gmx.de", "straus.translations@gmail.com", "therese.svardsten@gmail.com", "translation@cornell.hu", "vidiasc@gmail.com"];
const LANGS = $('Langs').first().json.langs; const gmap = $('Pick').first().json.gmap;
const NAMES = { es:'Spanish (Spain)', fr:'French (France)', it:'Italian', pt:'Portuguese (Brazil)', ro:'Romanian', pl:'Polish', lt:'Lithuanian', lv:'Latvian', de:'German', nl:'Dutch', da:'Danish', sv:'Swedish', no:'Norwegian Bokm\u00e5l', et:'Estonian', ms:'Malay', id:'Indonesian', ko:'Korean', th:'Thai' };
const GEN = { fa: 'This test is only for women: words referring to the reader are feminine.', ma: 'This test is only for men: words referring to the reader are masculine.', x: 'This test is for all genders: wording referring to the reader must be gender-neutral (never dual forms like (e), /a, (-a), \u0259).' };
const all = []; for (const it of $input.all()) { if (!Array.isArray(it.json.keys)) throw new Error('no keys'); all.push(...it.json.keys); }
const nm = k => typeof k.key_name === 'object' ? (k.key_name.web || k.key_name.other) : k.key_name;
const ord = p => p === 'start' ? -1 : p === 'end' ? 999 : parseInt(p.split('::')[1], 10);
const out = [];
for (const iso of LANGS) {
  const groups = {};
  for (const k of all) { const gm = gmap[k.key_id]; if (!gm) continue; const en = (k.translations||[]).find(t => t.language_iso === 'en'); const tr = (k.translations||[]).find(t => t.language_iso === iso);
    if (!tr || typeof tr.translation !== 'string' || !tr.translation) continue;
    (groups[gm[0]] = groups[gm[0]] || { test: gm[2], items: [] }).items.push({ i: tr.translation_id, kid: k.key_id, part: gm[1], en: en ? en.translation : '', t: tr.translation, lock: LING.includes(tr.modified_by_email) }); }
  const entries = Object.entries(groups).filter(([g, v]) => v.items.some(x => x.part === 'start') && v.items.some(x => !x.lock && x.part !== 'start'));
  let batch = [], n = 0;
  const flush = () => { if (!batch.length) return; const tests = [...new Set(batch.map(b => b.test))];
    const sys = 'You are a senior native ' + NAMES[iso] + ' copywriter and editor for Personality.co results profiles. You receive LIST GROUPS. Each group is one bullet list on the page: "start" is the intro line shown above the list (often ending in a colon, e.g. "You:" or "You may:"), "list::N" are the bullets in order, and "end" (if present) is a closing line after the list. TASK for each group: (1) every bullet must grammatically continue the start line \u2014 read "start + bullet" as one sentence and make it correct (e.g. if start ends with "You:" the bullets are verb phrases in the matching person/tense; if start is "You may:" they are infinitives/bare verbs as the language requires; if start introduces nouns, bullets are noun phrases); (2) all bullets in a group use the SAME form (same verb tense, person, mood, same type of phrase), same capitalization style and same end punctuation; (3) the end line reads naturally after the list. Change as little as possible: fix only form, agreement, tense, person, capitalization and punctuation, and adjust the start line only if that is the cleaner fix. Keep the meaning and the English sense. If an item has "lock": true it was edited by a professional linguist: return it unchanged and align the others to it. Gender rule per group given in "gender". Keep placeholders, HTML and line breaks exactly. If a group is already correct, return it unchanged. Reply with JSON only: {"items":[{"i":<id>,"t":"<string>"}]} for every input item.';
    const byg = {}; for (const b of batch) (byg[b.g] = byg[b.g] || { gender: GEN[b.test === 'fa' ? 'fa' : b.test === 'ma' ? 'ma' : 'x'], items: [] }).items.push({ i: b.i, part: b.part, en: b.en, t: b.t, lock: b.lock });
    out.push({ json: { iso, n: batch.length, body: { model: 'gpt-4.1', temperature: 0.1, response_format: { type: 'json_object' }, messages: [ { role: 'system', content: sys }, { role: 'user', content: JSON.stringify({ groups: Object.entries(byg).map(([g, v]) => ({ group: g, gender: v.gender, items: v.items })) }) } ] }, src: batch } }); batch = []; };
  for (const [g, v] of entries) { v.items.sort((a, b) => ord(a.part) - ord(b.part)); if (batch.length + v.items.length > 40) flush(); for (const x of v.items) batch.push(Object.assign({ g, test: v.test }, x)); }
  flush(); }
return out;

const reqs = $('Build batches').all(); const res = $input.all(); const rows = []; const errs = [];
const ph = s => (s.match(/\[%\d\$s:[^\]]+\]|\{\{[^}]+\}\}|<[^>]+>/g) || []).sort().join('|'); const nl = s => (s.match(/\n/g) || []).length;
res.forEach((it, i) => { const r = reqs[i].json; let parsed = null;
  try { parsed = JSON.parse(it.json.choices[0].message.content); } catch (e) { errs.push({ iso: r.iso, e: String(e).slice(0,200) }); return; }
  const m = {}; for (const x of (parsed.items||[])) m[String(x.i)] = x.t;
  for (const s of r.src) { if (s.lock) continue; const nt = m[String(s.i)]; if (typeof nt !== 'string') { errs.push({ iso: r.iso, missing: s.i }); continue; } if (nt === s.t) continue;
    const flags = []; if (ph(nt) !== ph(s.t)) flags.push('placeholder/html'); if (nl(nt) !== nl(s.t)) flags.push('linebreaks');
    rows.push({ iso: r.iso, g: s.g, test: s.test, part: s.part, tid: s.i, kid: s.kid, en: s.en, old: s.t, new: nt, flags }); } });
return [{ json: { n: rows.length, errs, rows } }];
